package com.musicdl.core

import com.musicdl.core.source.VkStreamUrlDecoder
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Golden vectors are the ones vk-fast asserts in `src/web_audio.rs`: the first four were captured
 * from real VK responses, the `AqS*` ones were generated by the website's own BigInt branch, so a
 * port that "looks right" but uses 32-bit math for `i` fails here instead of on a user's download.
 */
class VkStreamUrlDecoderTest {

    private val expected = "https://audio.example.test/track/index.m3u8?token=synthetic"
    private val prefix = "https://vk.ru/mp3/audio_api_unavailable.mp3?extra="

    @Test
    fun decodesOperationVectors() {
        val vectors = listOf(
            "AhrOChm6lY9HDwrPBY5LEgfTCgXLlNrLC3qVDhjHy2SVAw5KzxGUBtn1od9OB2TLBJ1ZEw5OAgvOAwm" to "",
            "y2LOzwHOBNLZpw5LA29OpZH1m2OUEgvKBMKVA2nHCNqVDhnLDc5LBhbTyxHLlM9PzhvHlY86C3bODgG" to "DG",
            "iZ8/oZHXzgqQpI8IjguUmY0MoYCUzt8Uod9KpZKQkcbKiIuVlJnLjNG+C3q/jcaUjxy4mIu/iY4/iIG" to "EaTl",
            "kci/lIm/jti4DIuUicq/Dhm+EczLmY4VjsjKicGQot9KpZGUp2uUjZSMkJmUzsqIlZ4QzgrXodS/pYm" to "DGL4cOS",
        )
        vectors.forEach { (data, operations) ->
            assertEquals(expected, VkStreamUrlDecoder.decode("$prefix$data#$operations", 42))
        }
    }

    @Test
    fun decodesAccountBoundOperationsWithBigIntMath() {
        val vectors = listOf(
            Triple(42L, "ChbOzgvZp21HB3qUzweUAxH1Ahr0C3rRlMLLB3rUBc9LDc8Vl3nOBwvPywnUztHKExiZDt1REhrUyZ0", "AqSZnW"),
            Triple(3_000_000_001L, "DgTLDgG4zhnUywLUCgvLCY5PCMf1Bc94Dc5TB3LWAs8VyZ9OmZP4DgvZDhrLy2qVBNvHps50zw1OA28", "AqSXnW"),
            Triple(4_294_967_301L, "Ac8VBw1WC3HOzhrOC3j5Axn4zwfOlI9LDdnPogXLyw9OpZ1OAwnRBI46BMfWB3vOBNvLyY50zwrLl2S", "AqS3mW"),
            Triple(9_007_199_254_740_991L, "AgvWl29Ol3rLlI9KDhHZpw55C2vHl2vZm29Oyw5TDwT1y3bOAwLOBI46BgLLlMrLCMnHp3H0Dg1OogS", "AqSTmty"),
            Triple(42L, "AgvUDgvTEhbVy2rZy3i6Dgv5lI9Ol3nVCgLOptm4DhmVDwuVyw54DgfRBhq/zwqUAxvUys50zw1PA3q", "AqS5mda3mtK5mJuOnZqWotKZ"),
        )
        vectors.forEach { (viewer, data, operations) ->
            assertEquals(
                "viewer=$viewer",
                expected,
                VkStreamUrlDecoder.decode("$prefix$data#$operations", viewer),
            )
        }
    }

    @Test
    fun keepsPlainLinksAndRejectsPlaceholders() {
        val plain = "https://cs1-50v4.vkuseraudio.net/p19/abc123/index.m3u8?extra_token=x"
        assertEquals(plain, VkStreamUrlDecoder.decode(plain, 42))
        assertNull(VkStreamUrlDecoder.decode("$prefix}not-valid#unknown", 42))
        assertNull(VkStreamUrlDecoder.decode("$prefix}missing-operations", 42))
        assertNull(VkStreamUrlDecoder.decode("http://insecure.example.test/a.mp3", 42))
        assertNull(VkStreamUrlDecoder.decode("https://127.0.0.1/a.mp3", 42))
        assertNull(VkStreamUrlDecoder.decode("https://localhost/a.mp3", 42))
        assertNull(VkStreamUrlDecoder.decode("", 42))
    }

    @Test
    fun legacyShuffleMatchesReferenceVector() {
        // vk-fast: shuffle(b"abcdefghijklmnopqrstuvwxyz", 37) == b"fycnwadlkjboutvxzerpgmishq"
        val data = "abcdefghijklmnopqrstuvwxyz".toByteArray()
        assertTrue(VkStreamUrlDecoder.legacyShuffle(data, 37L))
        assertEquals("fycnwadlkjboutvxzerpgmishq", String(data))
    }
}
